-- Migration 0001 — initial schema.
--
-- Design notes:
--   * All ids are TEXT (UUIDs generated by the application) so the storage
--     layer never depends on AUTOINCREMENT behaviour.
--   * Timestamps are RFC 3339 UTC TEXT, which sorts lexicographically and
--     stays human-readable when inspecting the database by hand.
--   * Enumerations are stored as their stable lowercase strings (see
--     `models::common::string_enum`), not as integer codes, so the meaning of
--     a row survives reordering of Rust variants.
--   * `metadata` columns hold a JSON object for platform-specific extras that
--     the domain models do not normalize.
--   * `downloads` and `download_history` intentionally carry no foreign keys:
--     they are operational records that must outlive the content rows they
--     refer to (a download of a since-deleted post is still history).

CREATE TABLE creators (
    id            TEXT PRIMARY KEY,
    platform      TEXT NOT NULL,
    platform_id   TEXT NOT NULL,
    handle        TEXT,
    display_name  TEXT NOT NULL,
    avatar_url    TEXT,
    description   TEXT,
    verified      INTEGER NOT NULL DEFAULT 0,
    post_count    INTEGER,
    profile_url   TEXT NOT NULL,
    metadata      TEXT NOT NULL DEFAULT '{}',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    UNIQUE (platform, platform_id)
);

CREATE TABLE posts (
    id                TEXT PRIMARY KEY,
    platform          TEXT NOT NULL,
    platform_post_id  TEXT NOT NULL,
    creator_id        TEXT REFERENCES creators (id) ON DELETE SET NULL,
    creator_handle    TEXT,
    url               TEXT NOT NULL,
    canonical_url     TEXT,
    caption           TEXT,
    media_type        TEXT NOT NULL,
    thumbnail_url     TEXT,
    published_at      TEXT,
    status            TEXT NOT NULL,
    metadata          TEXT NOT NULL DEFAULT '{}',
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL,
    UNIQUE (platform, platform_post_id)
);

CREATE INDEX idx_posts_creator_id ON posts (creator_id);
CREATE INDEX idx_posts_published_at ON posts (published_at DESC);

CREATE TABLE media_items (
    id                TEXT PRIMARY KEY,
    post_id           TEXT NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
    media_type        TEXT NOT NULL,
    source_url        TEXT NOT NULL,
    thumbnail_url     TEXT,
    mime_type         TEXT,
    extension         TEXT,
    width             INTEGER,
    height            INTEGER,
    duration_seconds  REAL,
    file_size         INTEGER,
    metadata          TEXT NOT NULL DEFAULT '{}',
    created_at        TEXT NOT NULL
);

CREATE INDEX idx_media_items_post_id ON media_items (post_id);

CREATE TABLE media_variants (
    id             TEXT PRIMARY KEY,
    media_item_id  TEXT NOT NULL REFERENCES media_items (id) ON DELETE CASCADE,
    kind           TEXT NOT NULL,
    label          TEXT NOT NULL,
    source_url     TEXT NOT NULL,
    mime_type      TEXT,
    extension      TEXT,
    width          INTEGER,
    height         INTEGER,
    file_size      INTEGER,
    bitrate_kbps   INTEGER,
    is_original    INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX idx_media_variants_item_id ON media_variants (media_item_id);

CREATE TABLE downloads (
    id                TEXT PRIMARY KEY,
    post_id           TEXT,
    media_item_id     TEXT,
    variant_id        TEXT,
    source_url        TEXT NOT NULL,
    destination_path  TEXT,
    file_name         TEXT,
    media_type        TEXT NOT NULL,
    state             TEXT NOT NULL,
    attempts          INTEGER NOT NULL DEFAULT 0,
    max_attempts      INTEGER NOT NULL DEFAULT 3,
    downloaded_bytes  INTEGER NOT NULL DEFAULT 0,
    total_bytes       INTEGER,
    error             TEXT,
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL,
    started_at        TEXT,
    completed_at      TEXT
);

CREATE INDEX idx_downloads_state ON downloads (state);
CREATE INDEX idx_downloads_created_at ON downloads (created_at DESC);

CREATE TABLE download_history (
    id             TEXT PRIMARY KEY,
    task_id        TEXT,
    post_id        TEXT,
    post_url       TEXT,
    creator_id     TEXT,
    creator_name   TEXT,
    media_type     TEXT NOT NULL,
    source_url     TEXT NOT NULL,
    local_path     TEXT,
    file_size      INTEGER,
    status         TEXT NOT NULL,
    error          TEXT,
    downloaded_at  TEXT NOT NULL
);

CREATE INDEX idx_history_downloaded_at ON download_history (downloaded_at DESC);
CREATE INDEX idx_history_post_id ON download_history (post_id);

CREATE TABLE settings (
    key         TEXT PRIMARY KEY,
    value       TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);
